class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next


def dedupe_sorted_chain(values):
    dummy = ListNode()
    tail = dummy
    for v in values:
        tail.next = ListNode(v)
        tail = tail.next
    head = dummy.next
    curr = head
    while curr and curr.next:
        if curr.val == curr.next.val:
            curr.next = curr.next.next
        else:
            curr = curr.next
    out = []
    node = head
    while node:
        out.append(node.val)
        node = node.next
    return out
